canvas.addEventListener('pointerdown',e=>{if(!$('#welcome').hidden||speech.isOpen())return;canvas.focus();const p=pointer(e);canvas.setPointerCapture(e.pointerId);if(['fair','workshop'].includes(scene)){const spot=worldHit(p);goal={x:spot?.x??p.x,y:Math.min(690,Math.max(310,spot?.y??p.y)),action:spot?.id};return;}if(scene==='tool'){if(!s.removed&&toolLit(s.toolEdges,false)&&hit(p,850,440,300,88)){prepareTester();return;}if(s.removed){const n=probes.findIndex(v=>distance(v,p)<30);if(n>=0){drag={kind:'probe',n};return;}}else{const port=Object.entries(toolPorts).find(([,v])=>Math.hypot(v[0]-p.x,v[1]-p.y)<25);if(port)drag={kind:'wire',from:+port[0],point:p};}return;}if(scene==='bench'){const n=probes.findIndex(v=>distance(v,p)<30);if(n>=0){drag={kind:'probe',n};snaps[n]=null;lastResult='';caption('正在移动检测头；尚未完成两端接触，不能判断器材好坏。将金属尖端对准蓝圈。');return;}if(hit(p,60,60,190,65)){lastResult='';snaps=[null,null];probes=[{x:820,y:590},{x:1010,y:590}];clearInspection();s.current.power=!s.current.power;s.current.verified=lit(s.current);log(s.current.power?'power_restored':'power_removed',{lit:s.current.verified});caption(s.current.power?(s.current.verified?'模型亮了！已有记录会自动补上复验状态；写过记录就可以直接交还作品。':'模型仍然不亮。换过器材不等于找到原因。'):'模型电池已取下，可以使用检测器。');tone(s.current.verified);return;}if(hit(p,280,60,190,65)){if(s.current.power){caption('先取下模型电池，再拧紧灯泡。');return;}tightenBulb();return;}if(hit(p,500,60,150,65)){drag={kind:'spare',target:'lamp',point:p,fromTray:true};caption('拿起备用小灯泡，拖到模型的玻璃灯泡或螺口处；灯座和导线保持原位。不想用时，拖回或再点一次“备用小灯泡”即可放回，也可按 Esc。');return;}if(hit(p,670,60,150,65)){drag={kind:'spare',target:'wire',point:p,fromTray:true};caption('把备用导线拖到模型的长导线上；请观察当前布局。不想用时，拖回或再点一次“备用长导线”即可放回，也可按 Esc。');return;}const ps=ports();const sw=ps[4],end=ps[5];if(hit(p,Math.min(sw[0],end[0])-25,sw[1]-45,190,90)){lastResult='';snaps=[null,null];s.current.closed=!s.current.closed;s.current.verified=lit(s.current);log('switch_toggled',{closed:s.current.closed,lit:s.current.verified});caption(s.current.closed?'开关合上了。观察模型灯有没有变化。':'开关打开了，回路中断。');tone(s.current.verified);}}});
canvas.addEventListener('pointermove',e=>{if(!drag)return;const p=pointer(e);drag.point=p;if(drag.kind==='spare'&&drag.fromTray&&!(p.y>=60&&p.y<=125&&(drag.target==='wire'?p.x>=670&&p.x<=820:p.x>=500&&p.x<=650)))drag.leftTray=true;if(drag.kind==='probe')probes[drag.n]=p;});
canvas.addEventListener('pointerup',e=>{if(!drag)return;const p=pointer(e),d=drag;drag=null;if(d.kind==='wire'){const end=Object.entries(toolPorts).find(([,v])=>Math.hypot(v[0]-p.x,v[1]-p.y)<28);if(end){const a=selectedToolPort??d.from,b=+end[0];selectedToolPort=null;if(a===b){selectedToolPort=b;caption('已选中接点，再点击另一个接点完成连接；也可以直接拖动。');return;}if((a===0&&b===1)||(a===1&&b===0)){caption('不要直接连接电池两极，这会短路。此连接已阻止。');log('short_circuit_blocked');return;}if(!s.toolEdges.some(([x,y])=>x===a&&y===b||x===b&&y===a))s.toolEdges.push([a,b]);log('tool_wire_connected',{a,b});caption(toolLit(s.toolEdges,false)?'自己的灯亮了！点击实验桌右侧蓝色“下一步：取下开关”按钮，留下两个检测头。':'导线已连接。观察哪些端点还没有形成完整回路。');tone(toolLit(s.toolEdges,false));}return;}if(d.kind==='probe'){if(scene==='bench'){lastResult='';}if((scene==='tool'||!inspectionPrepared)&&distance(probes[0],probes[1])<25){ready=true;s.toolReady=true;lastResult='亮';snaps=[null,null];log('tester_self_checked');caption('首次自检成功！电路检测器可以持续使用，不用反复自检；想再次确认时，也可让两个检测头互碰。');tone(true);return;}if(scene==='bench'){const port=Object.entries(detectionPorts()).sort((a,b)=>Math.hypot(a[1][0]-p.x,a[1][1]-p.y)-Math.hypot(b[1][0]-p.x,b[1][1]-p.y)).find(([,v])=>Math.hypot(v[0]-p.x,v[1]-p.y)<30);snaps[d.n]=port?.[0]??null;if(port)probes[d.n]={x:port[1][0],y:port[1][1]};log('probe_placed',{probe:d.n,port:snaps[d.n]});autoDetect();}return;}if(d.kind==='spare'){const ps=ports(),onTray=p.y>=60&&p.y<=125&&(d.target==='wire'?p.x>=670&&p.x<=820:p.x>=500&&p.x<=650);if(onTray&&(!d.fromTray||d.leftTray)){heldSpare=null;caption('已放回'+(d.target==='wire'?'备用长导线':'备用小灯泡')+'。需要时可再次拿取。');return;}if(onTray){heldSpare=d.target;drag={...d,point:p};caption('已拿起'+(d.target==='wire'?'备用导线':'备用灯泡')+'，点击模型对应部位使用；拖回或再点原备用按钮可放回，也可按 Esc。');return;}const matches=d.target==='wire'?pointNearSegment(p,ps[3],ps[4],48):lampDropMatches(p,ps[2],ps[3]);if(matches){heldSpare=null;repair(d.target);}else{heldSpare=d.target;drag={...d,point:p};caption('还未放到对应部位。可继续移动后点击放下；拖回或再点原备用按钮可放回，也可按 Esc。');}}});
canvas.addEventListener('pointercancel',()=>{drag=null;heldSpare=null;});
canvas.addEventListener('pointerdown',e=>{if(scene==='bench'&&heldSpare&&!$('#dialog').open&&!speech.isOpen()){const p=pointer(e),target=heldSpare;if(hit(p,target==='wire'?670:500,60,150,65)){heldSpare=null;drag=null;caption('已放回'+(target==='wire'?'备用长导线':'备用小灯泡')+'。需要时可再次拿取。');}else{drag={kind:'spare',target,point:p};canvas.setPointerCapture(e.pointerId);}e.stopImmediatePropagation();}},true);
window.addEventListener('keydown',e=>{if(e.key==='Escape'&&scene==='bench'&&!$('#dialog').open&&!speech.isOpen()&&(heldSpare||drag?.kind==='spare')){heldSpare=null;drag=null;caption('已放回备用器材。');}});
canvas.addEventListener('pointerdown',e=>{if(!$('#welcome').hidden||speech.isOpen()||!['fair','workshop'].includes(scene))return;const p=pointer(e),spot=worldHit(p);if(spot){canvas.focus();goal={...approachSpot(spot),action:spot.id};e.stopImmediatePropagation();}},true);
window.addEventListener('keydown',e=>{if(e.target.matches('input,textarea,select')||$('#dialog').open||speech.isOpen()||!$('#welcome').hidden)return;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();keys[e.key.toLowerCase()]=true;if(e.key.toLowerCase()==='e'&&['fair','workshop'].includes(scene)){const spot=nearestSpot(worldSpots(),player,135);if(spot)interact(spot.id);else caption('靠近同学、工坊门或工作台，再按 E 互动。');}});window.addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);window.addEventListener('blur',()=>keys={});
function shape(x,y,w,h,color,r=16){ctx.save();if(h===65){const g=ctx.createLinearGradient(x,y,x,y+h);g.addColorStop(0,'#fffdf1');g.addColorStop(1,color);ctx.fillStyle=g;ctx.shadowColor='#546c4d30';ctx.shadowBlur=12;ctx.shadowOffsetY=5;r=22;}else ctx.fillStyle=color;ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fill();if(h===65){ctx.shadowBlur=0;ctx.strokeStyle='#ffffffb0';ctx.lineWidth=3;ctx.stroke();}ctx.restore();}
function text(t,x,y,size=20,color='#35584e',align='center'){ctx.font=`600 ${size}px "Microsoft YaHei",sans-serif`;ctx.fillStyle=color;ctx.textAlign=align;ctx.fillText(t,x,y);}
function circle(x,y,r,color){ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fillStyle=color;ctx.fill();}
function line(a,b,color='#54949b',width=9){ctx.beginPath();ctx.moveTo(...a);ctx.lineTo(...b);ctx.strokeStyle=color;ctx.lineWidth=width;ctx.lineCap='round';ctx.stroke();}
function drawPlayer(x,y,scale=1){ctx.save();ctx.translate(x,y);ctx.scale(scale,scale);ctx.fillStyle='#244b3e25';ctx.beginPath();ctx.ellipse(0,1,30,9,0,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#51c5b4';ctx.lineWidth=3;ctx.beginPath();ctx.ellipse(0,2,38,12,0,0,Math.PI*2);ctx.stroke();const moving=!!goal||Object.values(keys).some(Boolean),bounce=moving?Math.sin(clock*.18)*3:Math.sin(clock*.025);drawStudent(ctx,s.avatar,-45,-160+bounce,90,160);shape(-22,-186,44,24,'#267d6bea',10);text('你',0,-169,13,'white');if(s.carrying)drawCraft(ctx,s.index,21,-86,68,68);ctx.restore();}
function npcSprite(index,x,y,size=125,walking=false,sheet=npcSheet,columns=3){if(!sheet.complete||!sheet.naturalWidth)return;ctx.save();ctx.fillStyle='#30554325';ctx.beginPath();ctx.ellipse(x,y,32,9,0,0,7);ctx.fill();const sw=sheet.naturalWidth/columns,sh=sheet.naturalHeight;const width=size*sw/sh,bob=walking?Math.sin(clock*.13)*2:0;ctx.drawImage(sheet,index*sw,0,sw,sh,x-width/2,y-size+bob,width,size);ctx.restore();}
function drawResident(a){const qi=questOwners.findIndex(q=>q.id===a.id);if(qi>=0&&qi<3&&emotions.complete&&emotions.naturalWidth){const w=emotions.naturalWidth/3,h=emotions.naturalHeight/2,row=s.reports.some(r=>r.index===qi)?1:0;ctx.drawImage(emotions,qi*w,row*h,w,h,a.x-a.size/2,a.y-a.size,a.size,a.size);}else npcSprite(a.sprite,a.x,a.y,a.size,!!a.moving,a.extra?extraSheet:npcSheet,a.extra?4:3);}
function drawFairNPCs(){
  const courier={id:'courier',...courierPosition(),sprite:1,size:138,extra:true};
  const actors=[...fairResidents,courier,{id:'player',...player}].sort((a,b)=>a.y-b.y);
  actors.forEach(a=>a.id==='player'?drawPlayer(a.x,a.y,1.15):drawResident(a));
}
function lighthouse(x,y,on){shape(x-35,y-90,70,90,'#fff0d2');shape(x-48,y-100,96,20,'#d37667');shape(x-42,y-145,84,45,on?'#ffe898':'#9aafb2');if(on){ctx.save();ctx.shadowColor='#ffc74a';ctx.shadowBlur=35;circle(x,y-120,18,'#ffdf68');ctx.restore();}text('灯塔寻宝',x,y+30,17);}
function drawWorld(){
  if(workshopArt.complete&&workshopArt.naturalWidth)ctx.drawImage(workshopArt,0,0,1200,760);
  else {shape(0,0,1200,760,'#c7e1d4',0);text('工坊场景正在加载…',600,180,24);}
  workshopSpots.forEach(t=>{
    const near=nearestSpot(workshopSpots,player,135)?.id===t.id;
    const y=t.id==='door'?t.y+45:t.y-75;
    shape(t.x-90,y,180,35,near?'#24786cf0':'#fff8e5e8',12);
    text(t.label,t.x,y+24,16,near?'white':'#496d62');
    if(near){shape(t.x-90,t.y+68,180,30,'#24786cf0',12);text(t.id==='door'?'走入门口自动离开':'E / 点击操作',t.x,t.y+89,14,'white');}
  });
  // Foreground stays empty; actors stand on the floor, not inside painted furniture.
  drawPlayer(player.x,player.y,1.15);
  if(s.current.verified){ctx.save();ctx.shadowColor='#ffda65';ctx.shadowBlur=25;circle(854,230,9,'#ffe9a2');ctx.restore();}
}
function drawBench(){drawDesk();shape(60,60,190,65,s.current.power?'#fcf3db':'#cfebdc');text(s.current.power?'取下模型电池':'放回电池复验',155,100,18);shape(280,60,190,65,'#e4f1ff');text('拧紧灯泡',375,100,18);shape(500,60,150,65,'#fcf3db');drawLooseBulb(ctx,575,82,.63);text(drag?.kind==='spare'&&drag.target==='lamp'?'点此放回小灯泡':'备用小灯泡',575,119,15);shape(670,60,150,65,'#fcf3db');drawPart(ctx,'wire',685,65,120,43);text(drag?.kind==='spare'&&drag.target==='wire'?'点此放回导线':'备用长导线',745,119,15);shape(840,60,180,65,'#e4f1ff');text('换上正常电池',930,100,17);const p=ports(),c=s.current,on=lit(c);[[0,2],[3,4],[5,1]].forEach(([a,b])=>{if(inspectionPrepared&&(inspectionTarget==='wire'&&a===3||['lamp','contact'].includes(inspectionTarget)&&a===0||inspectionTarget==='switch'&&(a===3||a===5))){ctx.save();ctx.setLineDash([8,8]);line(p[a],p[b],'#899ca066',3);ctx.restore();}else drawLead(ctx,p[a],p[b],'#b85f4e',8);});drawPart(ctx,c.power?'battery':'emptyBattery',p[0][0]-80,p[0][1],160,p[1][1]-p[0][1]);text(c.power?'电池已装入':'电池已取下',p[0][0],530,18);if(!(inspectionPrepared&&inspectionTarget==='contact'))drawBulb((p[2][0]+p[3][0])/2,240,on,'模型小灯泡');else text('灯泡与灯座已取下', (p[2][0]+p[3][0])/2,200,18);if(!(inspectionPrepared&&inspectionTarget==='switch'))drawSwitch(ctx,p[4],p[5],c.closed);text(c.closed?'开关：合上':'开关：打开',(p[4][0]+p[5][0])/2,530,18);text('整根导线 · 检查两端即可',p[3][0]+(s.index===2?-50:50),375,16);Object.values(p).forEach(([x,y])=>{circle(x,y,12,'#d4a24f');circle(x,y,6,'#fce9aa');});drawInspection();drawTester();if(drag?.kind==='spare'){if(drag.target==='wire')drawSpareWire(drag.point.x,drag.point.y);else drawLooseBulb(ctx,drag.point.x,drag.point.y);}if(tighteningUntil>performance.now()){const x=(p[2][0]+p[3][0])/2;ctx.save();ctx.strokeStyle='#218fd3';ctx.lineWidth=5;ctx.beginPath();ctx.arc(x,180,54,clock*.1,clock*.1+4.7);ctx.stroke();ctx.restore();text('正在将灯泡旋入灯座…',x,300,18,'#135b85');}}

function drawDesk(){if(deskArt.complete&&deskArt.naturalWidth)ctx.drawImage(deskArt,0,0,1200,760);else{shape(0,0,1200,760,'#d8bc88',0);shape(30,150,1140,550,'#f3e6c9',25);}shape(45,45,1100,95,'#fff8e5d9',20);}
function drawProbeLeads(origins){for(let n=0;n<2;n++){const p=probes[n],a=origins[n],angle=n?-.4:.4,bx=p.x-Math.sin(angle)*36,by=p.y+Math.cos(angle)*36;ctx.beginPath();ctx.moveTo(...a);ctx.bezierCurveTo(a[0]+(n?110:-110),a[1]+85,bx+(n?65:-65),by+60,bx,by);ctx.strokeStyle=n?'#4589be':'#de7660';ctx.lineWidth=7;ctx.stroke();ctx.save();ctx.translate(p.x,p.y);ctx.rotate(angle);shape(-8,12,16,28,n?'#4a94c7':'#e9806b',6);shape(-4,-3,8,19,'#cba253',3);ctx.restore();ctx.save();ctx.strokeStyle=snaps[n]!==null?'#19835e':'#1889d1';ctx.lineWidth=3;ctx.beginPath();ctx.arc(p.x,p.y,(scene==='bench'&&inspectionPrepared&&inspectionTarget==='lamp'?12:22)+Math.sin(clock*.05)*2,0,Math.PI*2);ctx.stroke();ctx.restore();circle(p.x,p.y,4,'#fff6ce');text(snaps[n]!==null?'✓':String(n+1),p.x+28,p.y+8,17,'#135a83');}}

function drawTester(){if(inspectionPrepared&&inspectionTarget==='battery'){shape(790,520,335,168,'#edf6fff0',20);text('电池正在上方参考电路检查',957,578,18,'#195d87');text('两根带电检测头不接电池',957,617,18,'#195d87');return;}shape(790,520,335,168,'#fffdf2ee',20);text('检测器 · 看这盏灯的亮灭',958,547,18);const touching=!inspectionPrepared&&snaps.every(n=>n===null)&&distance(probes[0],probes[1])<25,measured=snaps[0]!==null&&snaps[1]!==null&&lastResult==='亮';drawPart(ctx,'battery',805,560,75,85);line([843,645],[898,622],'#718b70',5);drawBulb(955,620,(ready&&touching)||measured,'');drawProbeLeads([[843,560],[1012,622]]);text(lastResult?'检测器的灯：'+lastResult:s.toolReady?'✓ 首次自检已通过，可直接检测':'首次使用：让两个检测头互相接触',957,675,13);}
function drawBulb(x,y,on,label){const g=bulbGlass(x-83,y-98,166,145);if(on){ctx.save();const halo=ctx.createRadialGradient(g.x,g.y,2,g.x,g.y,g.rx*2.2);halo.addColorStop(0,'#ffda78c0');halo.addColorStop(1,'#ffe78c00');ctx.fillStyle=halo;ctx.beginPath();ctx.ellipse(g.x,g.y,g.rx*2.2,g.ry*2.2,0,0,Math.PI*2);ctx.fill();ctx.restore();}if(scene==='bench'&&label==='模型小灯泡'&&inspectionPrepared&&inspectionTarget==='lamp')drawLampBase(ctx,x-83,y-98,166,145);else drawPart(ctx,'bulb',x-83,y-98,166,145);if(on){ctx.save();ctx.beginPath();ctx.ellipse(g.x,g.y,g.rx*.94,g.ry*.94,0,0,Math.PI*2);ctx.clip();const glow=ctx.createRadialGradient(g.x,g.y+g.ry*.22,1,g.x,g.y,g.rx);glow.addColorStop(0,'#ffffff');glow.addColorStop(.5,'#fff494ed');glow.addColorStop(1,'#ffd65599');ctx.fillStyle=glow;ctx.fillRect(g.x-g.rx,g.y-g.ry,g.rx*2,g.ry*2);ctx.save();ctx.strokeStyle='#fffef4';ctx.lineWidth=2.5;ctx.shadowColor='#fff7b0';ctx.shadowBlur=10;ctx.beginPath();ctx.moveTo(g.x-6,g.y+5);ctx.lineTo(g.x-3,g.y+1);ctx.lineTo(g.x,g.y+5);ctx.lineTo(g.x+3,g.y+1);ctx.lineTo(g.x+6,g.y+5);ctx.stroke();ctx.restore();for(let i=0;i<6;i++){const t=((clock*.006+i/6)%1),px=g.x+Math.sin(i*2.4+t*2)*g.rx*.62,py=g.y+g.ry*(.8-t*1.6);ctx.globalAlpha=Math.sin(t*Math.PI)*.65;circle(px,py,1+(i%2)*.45,'#fff6cc');}ctx.restore();}if(label){text(label,x,y-105,18);shape(x-54,y+49,108,30,on?'#fff2a5':'#dce7ed',10);text(on?'☀ 已亮起':'未亮',x,y+70,18,on?'#795000':'#46617b');}}
function drawSpareWire(x,y){drawPart(ctx,'wire',x-135,y-55,270,115);text('备用长导线',x,y-64,16);}
function drawTool(){drawDesk();text(s.removed?'电路检测器 · 用自己的灯检查其他部位':'先确认自己的简易电路能正常工作',570,103,23);drawPart(ctx,'battery',157,225,176,225);drawBulb(670,225,s.removed?ready&&distance(probes[0],probes[1])<35:toolLit(s.toolEdges,false),'');text('自己的小灯泡＋灯座',670,155,16);if(!s.removed){drawSwitch(ctx,toolPorts[4],toolPorts[5],true);text(toolLit(s.toolEdges,false)?'电路已接通 → 点击右侧蓝色按钮':'连好电路后，这里会提示下一步',660,550,15);}s.toolEdges.forEach(([a,b])=>drawLead(ctx,toolPorts[a],toolPorts[b],'#bc6250',7));Object.entries(toolPorts).forEach(([id,[x,y]])=>{circle(x,y,15,'#d3a448');circle(x,y,6,'#fff0be');if(selectedToolPort===+id){ctx.strokeStyle='#2c9e89';ctx.lineWidth=5;ctx.beginPath();ctx.arc(x,y,26,0,7);ctx.stroke();}text(['电池＋','电池－','灯座接点','灯座接点',s.removed?'检测头 A':'开关接点',s.removed?'检测头 B':'开关接点'][id],x,y+35,13);});if(s.removed)drawProbeLeads([toolPorts[4],toolPorts[5]]);if(drag?.kind==='wire')line(toolPorts[drag.from],[drag.point.x,drag.point.y],'#6ca297');if(!s.removed&&toolLit(s.toolEdges,false)){shape(850,440,300,88,'#367fc9',18);text('下一步：取下开关',1000,475,21,'white');text('留下两个检测头 →',1000,505,17,'white');}shape(880,280,250,135,'#fff6dc',18);text(s.removed?'两个检测头之间':'我们为什么要先接线？',1005,316,17);text(s.removed?'留给待检查的部件':'先确认这套电池和灯泡能用',1005,349,15);text(s.removed?'接入后，看自己的灯':'再用它们检查其他部位',1005,382,15);text(s.removed?(s.toolReady?'首次自检成功，工具可以持续使用':'两个检测头互碰，确认自己的灯能亮'):'接线顺序由你选择，已有连接会保留',570,670,17);}
function frame(){clock++;if(!$('#dialog').open&&!speech.isOpen()&&$('#welcome').hidden&&['fair','workshop'].includes(scene)){let dx=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0),dy=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0);if(dx||dy){goal=null;const d=Math.hypot(dx,dy);player.x+=dx/d*4;player.y+=dy/d*4;}else if(goal){const d=distance(player,goal);if(d<8){const action=goal.action;goal=null;if(action)interact(action);}else{player.x+=(goal.x-player.x)/d*4;player.y+=(goal.y-player.y)/d*4;}}player.x=Math.max(65,Math.min(1130,player.x));player.y=Math.max(scene==='workshop'?440:320,Math.min(690,player.y));}if(!$('#dialog').open&&!speech.isOpen()&&$('#welcome').hidden&&!s.celebrating&&performance.now()-lastDoorCrossing>1100&&nearDoor(scene,player))setScene(scene==='fair'?'workshop':'fair');ctx.clearRect(0,0,1200,760);if(['fair','workshop'].includes(scene)){drawWorld();drawNavigationGuide();}else if(scene==='bench')drawBench();else drawTool();particles=particles.filter(p=>p.life-->0);particles.forEach(p=>{p.x+=p.vx;p.y+=p.vy;p.vy+=.16;circle(p.x,p.y,5,p.color);});requestAnimationFrame(frame);}
function openDialog(html){speech.close();keys={};drag=null;heldSpare=null;selectedToolPort=null;goal=null;$('#closeDialog').textContent='返回游戏';$('#dialogBody').innerHTML=html;$('#dialog').showModal();}
function notebook(){
  const c=s.current;selected=new Set(c.report?.ids||c.reportDraft?.ids||[]);
  const actions=c.fixed.map(k=>names[k]+(k==='contact'?'拧紧':'更换')).join('、')||'还没有调整或更换器材';
  openDialog(`<h2>调查本 · ${cases[s.index].title}</h2>
    <p class="hint">可以先写检测判断和修复记录，文字会自动保存。放回电池复验成功后，自动补上验证状态，无需再次提交同一份说明。</p>
    <div class="result"><b>① 我做了什么</b><p>操作记录：${actions}</p><b>② 我怎样确认修好了</b><p>${c.verified&&lit(c)?'✓ 已放回电池并合上开关，模型灯亮起。':'尚未完成通电复验。请回实验桌观察模型灯。'}</p></div>
    <h3>③ 自动记录的修复操作</h3><div class="repair-records">${(c.operations||c.fixed.map(target=>({target}))).map((op,i)=>`<p>操作 ${i+1}：${op.action||names[op.target]+'调整或更换'}（已完成）。这是修复操作，是否有效还要看通电复验。</p>`).join('')||'<p>还没有更换或调整器材。</p>'}</div><h3>④ 哪些检测发现帮助我判断？</h3>
    <p class="hint">可选：点击想引用的记录；不选时会参考已有记录。记录中注明检测方法：部件看检测器灯，电池看换入后的参考灯；模型是否修好还要通电复验。</p>
    <div class="evidence-grid">${c.evidence.map((e,i)=>`<button class="evidence-card ${selected.has(e.id)?'selected':''}" data-evidence="${e.id}">记录 ${i+1} · ${names[e.target]}<span>${e.afterRepair?'该部位调整后':'该部位调整前'}：${e.method==='reference-substitution'?'换入后参考灯':'检测器的灯'}${e.lit?'亮':'不亮'}</span></button>`).join('')||'<p>没有检测记录也可以在修复复验后交还作品，原因则需要谨慎说明。</p>'}</div>
    <div class="report"><label>我目前认为有问题的部位（也可以暂不确定）<select id="conclusion"><option value="">还不确定具体原因</option>${Object.entries(names).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></label>
    <label>我的修复与观察<textarea id="reason" placeholder="例如：我重新连接灯座。放回电池并合上开关后，模型灯亮了。我还没有检测原来的连接。"></textarea></label>
    <button class="primary" id="submitReport">保存记录</button><p id="reportFeedback" role="status"></p><button id="returnReport" hidden>返回游戏，交还作品</button></div>
    <button id="export">导出调查记录 JSON</button>`);
  $('#conclusion').value=c.report?.target||c.reportDraft?.target||'';
  $('#reason').value=c.report?.reason||c.reportDraft?.reason||'';
  $('#dialogBody').querySelectorAll('[data-evidence]').forEach(b=>b.onclick=()=>{const id=+b.dataset.evidence;selected.has(id)?selected.delete(id):selected.add(id);b.classList.toggle('selected');});
  const readNote=()=>({target:$('#conclusion').value,reason:$('#reason').value.trim(),ids:[...selected]});
  const feedback=()=>{const complete=!!c.report;$('#returnReport').hidden=false;$('#returnReport').textContent=complete?'返回游戏，交还作品':'回实验桌，放回电池复验';$('#reportFeedback').textContent=complete?'记录已保存，通电复验已完成，可直接交还作品，无需再次提交。'+c.report.feedback:'记录已保存。现在回实验桌放回电池复验；点亮后会自动完成这份报告，无需再写或提交一次。';};
  const autosave=()=>{c.reportDraft=readNote();synchronizeReport(c);storeInvestigation(s);try{localStorage.setItem(KEY,JSON.stringify(s));feedback();update();}catch{$('#reportFeedback').textContent='本机保存失败，请先导出记录。';}};
  $('#reason').oninput=autosave;$('#conclusion').onchange=autosave;
  $('#dialogBody').querySelectorAll('[data-evidence]').forEach(b=>b.onclick=()=>{const id=+b.dataset.evidence;selected.has(id)?selected.delete(id):selected.add(id);b.classList.toggle('selected');autosave();});
  $('#submitReport').onclick=()=>{c.reportDraft=readNote();if(!c.reportDraft.reason){$('#reportFeedback').textContent='请写一句你的检测发现或修复操作。可以先保存，之后再通电复验。';return;}synchronizeReport(c);log('report_saved',{pendingVerification:!c.report});feedback();caption(c.report?'记录和通电复验均已完成，可以交还作品。':'记录已保存，放回电池复验后会自动完成报告。');tone(true);};
  if(c.reportDraft?.reason||c.report?.reason)feedback();
  $('#returnReport').onclick=()=>{$('#dialog').close();caption(c.report&&c.verified?'带着修好的作品回游园会，交给摊位负责人阿圆！':'记录已保留。点击“放回电池复验”，点亮后可直接交还，不用再次提交记录。');};
  $('#export').onclick=()=>download('科学调查记录.json',JSON.stringify(s,null,2),'application/json');
}
function download(name,data,type){const url=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),500);}
function showSummary(record=s){openDialog('<div class="lesson-summary"><small>羽老师 · 今日实验回顾</small><h2>四盏灯背后的发现</h2><p>相同的“不亮”现象，可能来自不同部位。电路检测器用于检查部件能否连通；电池则换入正常参考电路，看参考灯能否工作。作品恢复点亮，还要靠修复后的通电复验确认。</p><p class="summary-question">一起想一想：你先怀疑什么？哪次检测改变了判断？如果一次换了几个部位，能确定最初原因吗？</p><div id="summaries"></div><button id="finalExport">导出四次记录与报告</button></div>');renderSummary($('#summaries'),record);$('#finalExport').onclick=()=>download('本课完整记录.json',JSON.stringify(record,null,2),'application/json');}
function teacher(){openDialog(`<h2>教师工具 · 本地研究记录</h2><p class="hint">建议课堂节奏：导入3分钟，观察猜想5分钟，工具制作6分钟，两个病例12分钟，迁移8分钟，证据交流6分钟。时间须通过试教校准，不强制等待。</p><div class="teacher-grid"><div>作品结案<br><b>${s.reports.length} / 4</b></div><div>检测记录<br><b>${s.events.filter(e=>e.type==='measurement').length}</b></div><div>主动求助<br><b>${s.events.filter(e=>e.type==='hint_requested').length}</b></div><div>修复尝试<br><b>${s.events.filter(e=>e.type==='repair').length}</b></div></div><p class="hint">没有服务器，不能实时查看其他学生。可让学生导出JSON，再在这里导入多个文件汇总；数据仅在本机处理。解释内容尚不自动评分。</p><input type="file" id="imports" accept=".json" multiple><div id="importResult"></div><button id="csv">导出本机事件CSV</button><button id="json">导出本机完整JSON</button>`);let imports=[];$('#imports').onchange=async e=>{imports=[];for(const file of e.target.files){try{const data=JSON.parse(await file.text());if(!Array.isArray(data.events)||!Array.isArray(data.reports))throw Error();imports.push(data);}catch{}}$('#importResult').textContent=`已读取 ${imports.length} 份记录，共 ${imports.reduce((a,b)=>a+b.reports.length,0)} 个结案。`;};$('#csv').onclick=()=>{const records=imports.length?imports:[s];const esc=v=>'"'+String(v??'').replaceAll('"','""')+'"';const rows=[['匿名编号','事件','病例','经过毫秒','细节'],...records.flatMap(r=>r.events.map(e=>[r.student,e.type,e.case+1,e.elapsed,JSON.stringify(e)]))];download('课堂过程事件.csv','\uFEFF'+rows.map(row=>row.map(esc).join(',')).join('\r\n'),'text/csv;charset=utf-8');};$('#json').onclick=()=>download('课堂记录.json',JSON.stringify(s,null,2),'application/json');}
$('#start').onclick=()=>{$('#welcome').hidden=true;unlockEntry();canvas.focus();log('lesson_started');caption(s.completed?'作品已经交齐，可以欣赏亮灯展示，或找羽老师回顾实验。':'米米、慢慢和团团都需要帮助。点击上方任一任务卡，选择你想先调查的作品。');if(scene==='tool')offerTesterIntro();};$('#sound').onclick=()=>{muted=!muted;$('#sound').textContent=muted?'开启声音':'关闭声音';tone(true);};$('#teacher').onclick=teacher;$('#restart').onclick=restartGame;$('#leave').onclick=()=>setScene('workshop');$('#notebook').onclick=()=>s.completed?showSummary():notebook();$('#book').onclick=()=>s.completed?showSummary():notebook();$('#closeDialog').onclick=()=>{$('#dialog').close();canvas.focus();};$('#help').onclick=()=>{log('hint_requested');openDialog('<h2>实验操作帮助</h2><p class="hint">同样是不亮，可能有哪些原因？<br>工具本身正常吗？<br>一次检测的亮或不亮，能说明哪一部分？<br>调整后，要怎样确认真的修好了？</p><p class="hint">操作帮助：方向键、WASD、点击地面，任意一种方式都可以移动，选择一种即可，无需同时使用。靠近物件按 E 或直接点击物件互动。工具台拖接点连线；自己的电路点亮后，点击上方按钮取下开关，留下两个检测头。实验桌下方可选部件，取出后点“连接检测头”，也可拖动两个金属尖端到蓝圈 A、B；整根导线一次检查两端即可。电池要换入正常参考电路检查，不能接在带电检测头之间。工具首次自检成功后可持续使用。取下模型电池后再测，修复后重新供电。</p>');};
const undo=document.createElement('button');undo.textContent='撤销连接 / 重查';$('#sceneTools').append(undo);undo.onclick=()=>{if(scene==='tool'){if(!s.removed){s.toolEdges.pop();log('tool_wire_undone');caption('最后一条连接已撤销。');}else caption('检测器已制作完成，可离开工具台。');}else if(scene==='bench'&&confirm('恢复模型的原始故障状态再调查？现有证据保留，重置操作会被记录。')){clearInspection();s.current.fixed=[];s.current.power=false;s.current.closed=true;s.current.verified=false;s.current.report=null;lastResult='';snaps=[null,null];log('case_restored');caption('模型恢复到原始待查状态，可重新获取修复前的证据。');}};
function drawCelebration(){
  if(evening.complete&&evening.naturalWidth)ctx.drawImage(evening,0,0,1200,760);else{ctx.drawImage(background,0,0,1200,760);shape(0,0,1200,760,'#17345c66',0);}
  shape(250,370,700,38,'#9c663ee6',13);shape(265,404,16,70,'#855737');shape(920,404,16,70,'#855737');
  [290,495,700,905].forEach((x,i)=>{ctx.save();ctx.shadowColor='#ffd875';ctx.shadowBlur=45;circle(x,340,36,'#ffd87855');ctx.restore();drawCraft(ctx,i,x-80,225,160,170);const light=i===0?[x+20,260]:i===1?[x+27,323]:[x,285];ctx.save();ctx.globalCompositeOperation='screen';const g=ctx.createRadialGradient(...light,2,...light,i===2?45:20);g.addColorStop(0,'#fff4b5e6');g.addColorStop(.35,'#ffd05a90');g.addColorStop(1,'#ffc95000');ctx.fillStyle=g;ctx.beginPath();ctx.arc(...light,i===2?45:20,0,Math.PI*2);ctx.fill();ctx.restore();shape(x-84,417,168,29,'#23463fd9',12);text(cases[i].title+' · 已点亮',x,437,14,'#fff3cd');});
  [...celebrationActors,{id:'player',...player}].sort((a,b)=>a.y-b.y).forEach(a=>a.id==='player'?drawPlayer(a.x,a.y,1.15):drawResident(a));
  text('你让游园会重新亮起来了',600,172,27,'#fff6d5');text('点击同学分享喜悦 · 找羽老师回顾实验',600,204,15,'#fff4d9');
  const m=celebrationActors.find(a=>a.id==='mentor');shape(m.x-90,m.y+28,180,28,'#fff9e8dd',12);text('羽老师 · 总结与报告',m.x,m.y+48,13);
}
const workshopDraw=drawWorld;drawWorld=()=>{
  if(scene!=='fair'){workshopDraw();return;}
  if(s.celebrating){drawCelebration();return;}
  if(background.complete&&background.naturalWidth)ctx.drawImage(background,0,0,1200,760);else shape(0,0,1200,760,'#bddab5',0);
  if(s.reports.length||s.completed){ctx.save();ctx.shadowBlur=40;ctx.shadowColor='#ffd66b';circle(1010,263,13,'#ffe79b');ctx.restore();}
  drawFairNPCs();
  questOwners.slice(0,3).forEach((q,i)=>{const t=fairResidents.find(a=>a.id===q.id),status=questStatus(s,i),y=t.y-t.size-35;shape(t.x-84,y-25,168,49,status==='available'?'#fff1b9ed':'#fffaf0c9',12);text(q.name+' · '+cases[i].title,t.x,y-5,12);text(status==='delivered'?'✓ 已交还展示':status==='investigating'?'调查中 · 等你的发现':status==='paused'?'已暂存 · 等你继续':'? 有作品需要帮助',t.x,y+13,11,'#946b28');});
  const near=nearestSpot(worldSpots(),player,125);
  worldSpots().forEach(t=>{
    if(near?.id===t.id){
      const label=t.label;shape(Math.min(970,Math.max(15,t.x-105)),Math.max(12,t.y-(t.size||135)-42),210,32,'#fffaf0ee',12);
      text(label,Math.min(1075,Math.max(120,t.x)),Math.max(34,t.y-(t.size||135)-20),14);
      const x=Math.min(990,Math.max(15,t.x-90)),y=Math.min(710,t.y+30);
      shape(x,y,180,30,'#24786cec',14);text(t.id==='door'?'靠近门口即可进入':'E / 点击交谈',x+90,y+21,14,'white');
    }else if(['door','stall'].includes(t.id)){shape(t.x-80,t.y+32,160,28,'#fffdf2da',14);text(t.label,t.x,t.y+52,13,'#497265');}
  });
  if(s.completed)text('游园会重新亮起来了！',600,175,29,'#fffdf0');
};

canvas.addEventListener('pointerup',e=>{if(drag?.kind==='probe'&&!s.removed&&distance(probes[0],probes[1])<35){drag=null;e.stopImmediatePropagation();caption('还没有完成电路检测器，请到工具台按上方说明制作；已有接线和记录会保留。');}},true);
