function showTesterIntro(){openDialog(testerIntro);$('#closeDialog').textContent=scene==='tool'?'明白了，回到制作台':'明白了，回到调查';}
function offerTesterIntro(){if(s.testerIntroSeen)return;s.testerIntroSeen=true;log('tester_introduced');showTesterIntro();}
function prepareTester(){if(s.removed)return;if(!toolLit(s.toolEdges,false)){caption('先让自己的简易电路亮起来，确认器材正常。现有连接会保留。');return;}s.removed=true;selectedToolPort=null;probes=[{x:610,y:450},{x:735,y:450}];log('tester_switch_removed');caption('开关的位置现在留下两个检测头。把它们互碰一下，确认自己的灯能亮，之后就可以检查作品了。');}
document.querySelectorAll('[data-avatar-choice]').forEach(b=>b.onclick=()=>{s.avatar=b.dataset.avatarChoice;log('avatar_selected',{avatar:s.avatar});});
function update(){updateBase();updateGuide();refreshBenchPanel();}
function updateGuide(){const phase=missionPhase(s,s.index);$('#questCount').textContent=s.reports.length+' / 4 已完成';$('#questBar').value=s.reports.length;$('#questCurrent').textContent=s.completed?'全部完成！参加亮灯展示，与羽老师交流':s.carrying?'当前：'+questOwners[s.index].name+' · '+phase.label:s.reports.length===3?'三件已交齐，阿圆有新的求助':'前三件自由选序，交齐后解锁摊主第四件';$('#notebook').firstChild.textContent=s.completed?'查看四次记录与报告 ':'打开调查本 ';$('#playerPortrait').dataset.avatar=s.avatar;$('#playerName').textContent=s.avatar==='girl'?'女生调查员':'男生调查员';document.querySelectorAll('[data-avatar-choice]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.avatarChoice===s.avatar)));const g=guideFor(s,scene,ready);$('#guideNumber').textContent=g.step+1;$('#guideTitle').textContent=g.title;$('#guideDetail').textContent=g.detail;$('#guideWhy').hidden=!['tool','bench'].includes(scene);$('#guideWhy').textContent='为什么这样做：'+testerPurpose(s);testerHelp.hidden=!['tool','bench'].includes(scene);const button=$('#guideAction');button.hidden=!g.target&&!g.action;button.textContent=g.target==='door'?(scene==='fair'?'前往工坊门口':'前往出口'):g.target==='stall'?'前往阿圆的摊位':g.target==='tool'?'前往制作台':g.target==='bench'?'前往实验桌':questOwners.some(q=>q.id===g.target)?'前往'+questOwners.find(q=>q.id===g.target).name+'身边':g.target==='mentor'?'前往羽老师身边':g.action==='notebook'?'打开调查本':g.action==='summary'?'查看本课发现':g.action==='prepare-tester'?'取下开关，留下两个检测头':'离开工作台';button.onclick=()=>{if(g.target){const spot=g.target==='door'?doorZones[scene]:worldSpots().find(t=>t.id===g.target);if(spot)goal=g.target==='door'?{x:spot.x,y:spot.y,action:null}:{...approachSpot(spot),action:spot.id};}else if(g.action==='notebook')notebook();else if(g.action==='summary')showSummary();else if(g.action==='prepare-tester')prepareTester();else setScene('workshop');};tasks.innerHTML=cases.map((c,i)=>'<button type="button" data-quest="'+i+'" class="craft-task '+(s.reports.some(r=>r.index===i)?'done':i===s.index&&s.carrying?'current':'waiting')+'"><span class="craft-thumb" data-craft="'+i+'" style="background-position:'+Math.min(i,2)*50+'% 50%"></span><div><small>作品 '+(i+1)+' / 4</small><b>'+c.title+'</b><small>'+questOwners[i].name+' · '+questOwners[i].place+'</small><span>'+(missionPhase(s,i).label)+'</span></div></button>').join('');tasks.querySelectorAll('[data-quest]').forEach(b=>{b.setAttribute('aria-label',questOwners[+b.dataset.quest].name+' · '+missionPhase(s,+b.dataset.quest).label+'，点击前往或查看');b.onclick=()=>navigateQuest(+b.dataset.quest);});$('#inventory').innerHTML='<div class="carried-craft"><span class="craft-thumb" data-craft="'+s.index+'" style="background-position:'+Math.min(s.index,2)*50+'% 50%"></span><div><b>'+cases[s.index].title+'</b><br>'+(s.completed?'四件作品均已交还':s.carrying?'已拿在手上':'找'+questOwners[s.index].name+'领取作品')+'<br>'+(s.toolReady?'✓ 自制检测器已备好':'检测工具尚未制作')+'</div></div>';}
function drawNavigationGuide(){if(s.celebrating)return;const g=guideFor(s,scene,ready),zone=doorZones[scene];if(zone){ctx.save();ctx.fillStyle='#69dbcd38';ctx.strokeStyle='#f5db8b';ctx.lineWidth=4;ctx.setLineDash([9,6]);ctx.beginPath();ctx.ellipse(zone.x,zone.y,zone.rx,zone.ry*.5,0,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.setLineDash([]);text(scene==='fair'?'走到这里 → 进入工坊':'走到这里 → 返回游园会',zone.x+35,zone.y+48,14,'#234f44');ctx.restore();}if(!g.target)return;const t=g.target==='door'?zone:worldSpots().find(p=>p.id===g.target);if(!t)return;const tx=t.x,ty=g.target==='door'?t.y:Math.max(scene==='workshop'?440:320,t.y+55);ctx.save();ctx.strokeStyle='#e9c568';ctx.lineWidth=3;ctx.setLineDash([3,14]);ctx.beginPath();ctx.moveTo(player.x,player.y+4);ctx.lineTo(tx,ty);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle='#fff4c5';ctx.strokeStyle='#b98232';ctx.lineWidth=2;const by=ty-25-Math.sin(clock*.07)*5;ctx.beginPath();ctx.moveTo(tx-12,by-15);ctx.lineTo(tx+12,by-15);ctx.lineTo(tx,by);ctx.closePath();ctx.fill();ctx.stroke();ctx.restore();}
// A selected component is physically separated before the powered continuity test.
const benchPanel=document.createElement('section');benchPanel.id='benchPanel';benchPanel.hidden=true;benchPanel.setAttribute('aria-label','实验操作与下一步');benchPanel.innerHTML='<div class="bench-heading"><b>我想检查…</b><span>任选部件，不必按顺序</span><button id="benchFold" aria-expanded="true">收起提示</button></div><div class="bench-content"><div class="bench-choices"></div><p class="bench-instruction"></p><div class="bench-actions"></div><p class="bench-feedback" role="status">先观察模型。选一个部件，看看它应该怎样检查。</p></div>';canvas.closest('.stage').append(benchPanel);
benchPanel.querySelector('.bench-choices').innerHTML=Object.entries({lamp:'小灯泡',wire:'整根导线',switch:'开关',contact:'灯泡与灯座',battery:'电池'}).map(([k,v])=>'<button data-inspect="'+k+'">'+v+'</button>').join('');
benchPanel.querySelectorAll('[data-inspect]').forEach(b=>b.onclick=()=>{clearInspection();inspectionTarget=b.dataset.inspect;refreshBenchPanel();caption(inspectionTarget==='battery'?'电池提供电能，不能接在带电检测头之间。我们把它换入已知正常的参考电路，观察参考灯。':'选中了'+names[inspectionTarget]+'。取下模型电池后，将这个部件单独取出检查；蓝色圆圈标出它的两个金属接触点。');});
$('#benchFold').onclick=()=>{const folded=benchPanel.classList.toggle('folded');$('#benchFold').textContent=folded?'展开提示':'收起提示';$('#benchFold').setAttribute('aria-expanded',String(!folded));};
function clearInspection(){heldSpare=null;drag=null;inspectionPrepared=false;inspectionTarget=null;snaps=[null,null];lastResult='';probes=[{x:820,y:590},{x:1010,y:590}];}
function detectionPorts(){if(!inspectionPrepared||inspectionTarget==='battery')return ports();const ends=inspectionTarget==='lamp'?[[524,394],[548,417]]:inspectionTarget==='contact'?[[500,416],[615,416]]:[[455,365],[650,365]];return {'10':ends[0],'11':ends[1]};}
function refreshBenchPanel(){benchPanel.hidden=scene!=='bench'||!$('#welcome').hidden;if(scene!=='bench')return;benchPanel.querySelectorAll('[data-inspect]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.inspect===inspectionTarget)));const c=s.current,t=inspectionTarget,instruction=benchPanel.querySelector('.bench-instruction'),actions=benchPanel.querySelector('.bench-actions');actions.replaceChildren();const action=(label,fn)=>{const b=document.createElement('button');b.textContent=label;b.onclick=fn;actions.append(b);};instruction.textContent=!t?'先猜想，再选一个部件。检测、调整、记录可自由安排；最后放回电池验证。':t==='battery'?'电池用换入法：先移出参考电路的正常电池，再换入作品电池。参考灯不亮，说明这节电池不能让已知正常的回路工作。':inspectionPrepared?'部件已与模型断开。将两个检测头的金属尖端分别放到蓝圈 A、B；也可点击“连接检测头”帮助接线。检测灯不亮时，先分清是未接好还是部件不通。':'先取下模型电池，再将选中的部件与模型断开，检查它本身。整根导线取出后，只接两端露出的金属头。灯亮说明能连通；两端接好仍不亮，可以换整根备用导线，再通电比较。不必一段段测。';if(!t)return;if(!s.toolReady){action('去制作检测器',()=>{setScene('tool');offerTesterIntro();});return;}if(c.power){action('取下模型电池',()=>{c.power=false;c.verified=false;log('power_removed');caption('电池已取下。现在可取出所选部件，连接检测头。');});return;}if(t==='battery'){action(inspectionPrepared?'再次检查电池':'换入待测电池',()=>{inspectionPrepared=true;snaps=[null,null];const r=testBattery(c,s.toolReady);if(r.blocked){caption(r.blocked);return;}lastResult=r.lit?'亮':'不亮';const e={...r,id:c.evidence.length,afterRepair:c.fixed.includes('battery'),time:Date.now()};c.evidence.push(e);log('measurement',e);caption('参考电路已移出正常电池，换入作品电池：参考灯'+lastResult+'。'+(r.lit?'这节电池能使参考灯工作，可检查其它部件。':'这节电池不能使已知正常的参考电路工作；可换上正常电池，再给作品通电比较。')+' 已保存记录。');tone(r.lit);});action('换上正常电池',()=>repair('battery'));return;}if(!inspectionPrepared){action('取出部件，显示两端',()=>{inspectionPrepared=true;snaps=[null,null];lastResult='';log('component_isolated',{target:t});caption(t==='contact'?'灯泡连同原灯座单独取下，两根外接导线已断开。检查灯泡和灯座这一整体；若不通，还要单独检查灯泡，才能区分原因。':'已取出'+names[t]+'。两个蓝圈就是它的金属接触位置，检测器不用搬动。');});}else{action('连接检测头 / 再测一次',()=>{const ps=detectionPorts();probes=[{x:ps[10][0],y:ps[10][1]},{x:ps[11][0],y:ps[11][1]}];snaps=['10','11'];autoDetect();});action('断开检测头',()=>{snaps=[null,null];lastResult='';probes=[{x:820,y:590},{x:1010,y:590}];caption('检测头已断开，现在没有检测结果；不等于器材损坏。');});}if(t==='contact')action('拧紧灯泡',tightenBulb);if(t==='lamp'||t==='wire')action(t==='lamp'?'换上备用小灯泡':'换上整根备用导线',()=>repair(t));if(t==='switch')action(c.closed?'打开开关再比较':'合上开关再比较',()=>{c.closed=!c.closed;lastResult='';log('switch_toggled',{closed:c.closed});if(snaps.every(n=>n!==null))autoDetect();else caption(c.closed?'开关已合上，连接两端再观察。':'开关已打开，连接两端再观察。');});}
function tightenBulb(){if(tighteningUntil>performance.now())return;if(s.current.power){caption('先取下模型电池，再拧紧灯泡。');return;}clearInspection();const current=s.current;tighteningUntil=performance.now()+1100;caption('正在拧紧灯泡，让螺口与灯座可靠接触…');setTimeout(()=>{if(scene!=='bench'||s.current!==current)return;repair('contact');caption('已将小灯泡拧紧到原灯座中，外接导线没有增加。放回模型电池，看看灯是否亮起。');},1100);}
function drawInspection(){if(!inspectionTarget)return;const t=inspectionTarget;if(!inspectionPrepared){if(t!=='battery'){const ps=ports(),ends=t==='wire'?[ps[3],ps[4]]:t==='switch'?[ps[4],ps[5]]:[ps[2],ps[3]];ends.forEach(([x,y],i)=>{ctx.save();ctx.strokeStyle='#1689d2';ctx.lineWidth=4;ctx.beginPath();ctx.arc(x,y,24,0,Math.PI*2);ctx.stroke();ctx.restore();text(i?'B':'A',x,y-30,20,'#116599');});}return;}shape(365,270,385,210,'#f1f9fff5',20);text(t==='battery'?'参考电路 · 已换入作品电池':'单独检查区 · '+names[t],557,295,18,'#195d87');if(t==='battery'){drawPart(ctx,'battery',420,330,60,85);drawBulb(640,390,lastResult==='亮','');drawLead(ctx,[450,330],[582,390],'#b85f4e',5);drawLead(ctx,[450,415],[697,390],'#4589be',5);text('原正常电池已移出',555,432,16,'#195d87');return;}const dp=detectionPorts(),a=dp[10],b=dp[11];if(t==='wire'){drawLead(ctx,a,b,'#b85f4e',10);line(a,[a[0]+12,a[1]],'#d0a34d',9);line([b[0]-12,b[1]],b,'#d0a34d',9);}else if(t==='switch')drawSwitch(ctx,a,b,s.current.closed);else if(t==='lamp'){drawLooseBulb(ctx,548,345,1.6);if(lastResult==='亮'){ctx.save();ctx.globalAlpha=.8;circle(548,345,34,'#fff8b8');ctx.restore();}text('A → 金属螺口 / B → 底部触点',557,449,16,'#195d87');}else{drawBulb(558,416,lastResult==='亮','');text('原灯泡＋原灯座，外接线已断开',557,435,15,'#195d87');}for(const [i,[x,y]] of [a,b].entries()){ctx.save();ctx.strokeStyle=snaps.includes(String(i+10))?'#19835e':'#1689d2';ctx.lineWidth=3;ctx.beginPath();ctx.arc(x,y,t==='lamp'?12:22,0,Math.PI*2);ctx.stroke();ctx.restore();text(i?'B':'A',x+(t==='lamp'?(i?27:-25):0),y-24,19,'#116599');}text(snaps.every(n=>n!==null)?'✓ 两端已接触 · 看检测灯':snaps.some(n=>n!==null)?'还差另一端 · 尚未完成连接':'未接触 · 尚不能判断好坏',557,468,18,'#195d87');}
canvas.addEventListener('pointerdown',e=>{if(scene!=='bench'||!$('#welcome').hidden||$('#dialog').open)return;const p=pointer(e);if(hit(p,840,60,180,65)){repair('battery');e.stopImmediatePropagation();}},true);
setInterval(()=>{undo.hidden=!['tool','bench'].includes(scene);$('#elapsed').textContent=`本次调查 ${Math.floor((Date.now()-s.started)/60000)} 分钟`;},500);update();frame();
if(new URLSearchParams(location.search).get('teacher')==='1')teacher();

const celebrationButton=document.createElement('button');celebrationButton.id='celebrationButton';celebrationButton.hidden=!s.completed||scene!=='fair';celebrationButton.textContent='欣赏亮灯展示';$('#sceneTools').append(celebrationButton);celebrationButton.onclick=()=>{if(s.celebrating){s.celebrating=false;setScene('fair');log('celebration_left');}else beginCelebration();};

function navigateQuest(index){if(!$('#welcome').hidden)return;if(index===3&&missionPhase(s,3).key==='locked'){caption('先交还三位同学的作品，阿圆就会提出第四个求助。');return;}speech.close();if(!s.completed&&s.reports.some(r=>r.index===index)){showSummary();return;}if(scene!=='fair')setScene('fair');const owner=worldSpots().find(p=>p.id===questOwners[index].id);if(owner)goal={...approachSpot(owner),action:owner.id};}

function restartGame(){openDialog('<h2>重新开始游戏</h2><p>请选择怎样处理本轮进度。以前已经保存的游玩记录都会保留。</p><div class="restart-options"><button id="saveAndRestart" class="primary">保存本轮记录，重新开始</button><p>保留本轮任务、检测和报告，之后可在“游玩记录”查看。</p><button id="discardAndRestart">不保存本轮，直接重新开始</button><p>放弃这次尚未保存为历史的进度，从头选择调查员；不会删除以前的历史记录。</p></div><button id="exportBeforeRestart">导出本轮记录</button><p id="restartStatus" role="status"></p>');$('#exportBeforeRestart').onclick=()=>download('本轮游玩记录.json',JSON.stringify(s,null,2),'application/json');const reset=save=>{try{if(save){s.scene=scene;s.player=player;storeInvestigation(s);archiveAndReset(localStorage,KEY,s);}else discardAndReset(localStorage,KEY);$('#saveAndRestart').disabled=true;$('#discardAndRestart').disabled=true;location.reload();}catch{$('#restartStatus').textContent=save?'未能安全保存历史记录，当前进度没有清除。请先导出本轮记录后重试。':'本轮进度未能清除，请重试；以前的历史记录没有改变。';}};$('#saveAndRestart').onclick=()=>reset(true);$('#discardAndRestart').onclick=()=>reset(false);}

function playHistory(){openDialog('<h2>以前的游玩记录</h2><p>每次选择“保存本轮记录，重新开始”，都会在本机保留一份完整记录。</p><div id="playHistoryList"></div><p class="hint">旧记录不会覆盖当前游戏。记录只在当前浏览器保存，请及时导出备份。</p>');try{const history=readPlayHistory(localStorage,KEY),list=$('#playHistoryList');if(!history.length){list.textContent='还没有保存的历史轮次。当前游戏可通过“重新开始”保存后重玩。';return;}history.forEach(entry=>{const card=document.createElement('article');card.className='summary-case';const title=document.createElement('h3');title.textContent=new Date(entry.savedAt).toLocaleString('zh-CN')+' · 已完成 '+entry.state.reports.length+' / '+(entry.state.investigations?.length||3);const view=document.createElement('button');view.textContent='查看记录与报告';view.onclick=()=>showSummary(entry.state);const exp=document.createElement('button');exp.textContent='导出这一轮';exp.onclick=()=>download('游玩记录-'+entry.id+'.json',JSON.stringify(entry.state,null,2),'application/json');card.append(title,view,exp);list.append(card);});}catch{$('#playHistoryList').textContent='历史记录暂时无法读取；当前进度没有改变。请先导出本轮数据。';}}
const historyButton=document.createElement('button');historyButton.id='playHistory';historyButton.textContent='游玩记录';document.querySelector('header').append(historyButton);historyButton.onclick=playHistory;

$('#sceneTools').append($('#restart'));

// Returning visitors make an explicit choice before any saved investigation resumes.
function unlockEntry(){for(const el of [tasks,guideRoot,$('aside'),$('#sceneTools')])el.inert=false;}
for(const el of [tasks,guideRoot,$('aside'),$('#sceneTools')])el.inert=true;
if(hasSavedProgress){
  const card=$('#welcome > div');card.classList.add('returning-entry');
  card.replaceChildren();
  const small=document.createElement('small');small.textContent='校园科学工坊 · 发现上次游玩进度';
  const title=document.createElement('h2');title.textContent='这次想继续，还是重新开始？';
  const detail=document.createElement('p');detail.textContent='上次已交付 '+s.reports.length+' / 4 件作品 · '+(scene==='tool'?'工具制作台':scene==='bench'?'模型实验桌':scene==='workshop'?'科学工坊':s.celebrating?'亮灯游园会':'校园游园会')+'。选择后再进入游戏。';
  const resume=document.createElement('button');resume.id='continueGame';resume.className='primary';resume.textContent='保持上次进度，继续游玩';
  resume.onclick=()=>{$('#welcome').hidden=true;unlockEntry();canvas.focus();log('lesson_resumed');caption(s.completed?'上次已完成四件作品，可欣赏亮灯展示或查看记录。':scene==='tool'?'已回到上次的工具制作台，已有接线保留。按上方提示继续即可。':scene==='bench'?'已回到上次的实验桌，器材、检测记录和报告保留。可在下方选择要检查的部件。':'已保留上次任务和记录，可按指引继续。');};
  const startNew=document.createElement('button');startNew.id='newGame';startNew.textContent='开始新游戏';startNew.onclick=restartGame;
  const note=document.createElement('p');note.textContent='继续游玩沿用原调查员，无需重新选择。开始新游戏时，可以选择保存或放弃本轮记录。';
  card.append(small,title,detail,resume,startNew,note);
}
